import { shuffle } from '../../random.js';

/** Board geometry for a target word length: 5 letters -> 2x3, 7 letters -> 2x4, others pick the closest fit. */
export const layoutFor = (n) => ({ rows: 2, cols: Math.ceil((n + 1) / 2) });

/**
 * Sliding Letter Puzzle: letters of a word sit on a small grid with one blank. Tiles next to the blank slide
 * into it. Puzzles are generated by making random legal moves from the solved state, so they are always reachable.
 * Solved state: letters in reading order spell the word, blank in the last cell.
 */
export class SlidingLetters {
  constructor({ word, tiles, moves = 0 }) {
    this.type = 'sliding';
    this.word = word;
    this.tiles = tiles; // array of letters, '' = blank
    this.moves = moves;
    const { rows, cols } = layoutFor(word.length);
    this.rows = rows;
    this.cols = cols;
  }

  static solvedTiles(word) {
    const { rows, cols } = layoutFor(word.length);
    const t = [...word];
    while (t.length < rows * cols) t.push('');
    return t;
  }

  static create({ word, rng, shuffles = 40 }) {
    const solved = SlidingLetters.solvedTiles(word);
    const p = new SlidingLetters({ word, tiles: solved.slice() });
    let last = -1;
    for (let i = 0; i < shuffles || p.isSolved(); i++) {
      const blank = p.tiles.indexOf('');
      const options = p.neighbors(blank).filter((n) => n !== last);
      const pick = shuffle(options, rng)[0];
      p.#slide(pick, blank);
      last = blank;
      if (i > 400) break;
    }
    p.moves = 0;
    return p;
  }

  neighbors(i) {
    const r = Math.floor(i / this.cols);
    const c = i % this.cols;
    const out = [];
    if (r > 0) out.push(i - this.cols);
    if (r < this.rows - 1) out.push(i + this.cols);
    if (c > 0) out.push(i - 1);
    if (c < this.cols - 1) out.push(i + 1);
    return out;
  }

  #slide(from, blank) {
    this.tiles[blank] = this.tiles[from];
    this.tiles[from] = '';
  }

  /** Slides the tile at index `i` into the blank if adjacent. */
  move(i) {
    if (!Number.isInteger(i) || i < 0 || i >= this.tiles.length || !this.tiles[i]) return false;
    const blank = this.tiles.indexOf('');
    if (!this.neighbors(blank).includes(i)) return false;
    this.#slide(i, blank);
    this.moves++;
    return true;
  }

  isSolved() { return this.tiles.join('') === this.word && this.tiles[this.tiles.length - 1] === ''; }

  toJSON() { return { type: this.type, word: this.word, tiles: this.tiles.slice(), moves: this.moves }; }

  static fromJSON(j) {
    if (!j || typeof j.word !== 'string' || !Array.isArray(j.tiles)) return null;
    const solved = SlidingLetters.solvedTiles(j.word);
    if (j.tiles.length !== solved.length || j.tiles.slice().sort().join('') !== solved.slice().sort().join('')) return null;
    return new SlidingLetters({ word: j.word, tiles: j.tiles.slice(), moves: Number.isInteger(j.moves) ? j.moves : 0 });
  }
}

/** Parity check used by tests: a grid is reachable when its permutation parity matches the solved state's. */
export function isReachable(puzzle) {
  const solved = SlidingLetters.solvedTiles(puzzle.word);
  const { cols } = layoutFor(puzzle.word.length);
  // BFS over states; the spaces are tiny (<= 8!/2 states for 3x3, far less here)
  const goal = solved.join('|');
  const start = puzzle.tiles.join('|');
  const seen = new Set([start]);
  const queue = [puzzle.tiles.slice()];
  while (queue.length) {
    const t = queue.shift();
    if (t.join('|') === goal) return true;
    const b = t.indexOf('');
    const r = Math.floor(b / cols);
    const c = b % cols;
    const ns = [];
    if (r > 0) ns.push(b - cols);
    if (r < puzzle.rows - 1) ns.push(b + cols);
    if (c > 0) ns.push(b - 1);
    if (c < cols - 1) ns.push(b + 1);
    for (const n of ns) {
      const u = t.slice();
      [u[b], u[n]] = [u[n], u[b]];
      const k = u.join('|');
      if (!seen.has(k)) { seen.add(k); queue.push(u); }
    }
  }
  return false;
}
